"use client";

import * as React from "react";
import { Button } from "@base-ui/react/button";
import { ScrollArea } from "@base-ui/react/scroll-area";
import { cn } from "@/lib/utils";
import "@/components/ui/whatsapp/styles/whatsapp.css";
import { TemplateButton } from "./template-bubble";

export interface CarouselCard {
  imageUrl?: string;
  body: string;
  buttons?: TemplateButton[];
}

export interface CarouselTemplateProps extends React.HTMLAttributes<HTMLDivElement> {
  body?: string;
  cards: CarouselCard[];
  timestamp?: string;
}

function CardButton({ button }: { button: TemplateButton }) {
  const base = "flex w-full items-center justify-center gap-1.5 py-[9px] text-[13px] font-medium text-wa-emerald-500";
  const label = button.type === "call_permission" ? `Call ${button.bizName}` : button.type === "copy_code" ? (button.label ?? "Copy offer code") : "label" in button ? button.label : "";

  const renderEl = button.type === "url" && button.url
    ? <a href={button.url} target="_blank" rel="noopener noreferrer" />
    : button.type === "phone_number" && button.phone_number
    ? <a href={`tel:${button.phone_number}`} />
    : undefined;

  return (
    <Button render={renderEl} nativeButton={renderEl == null} className={base}>
      {button.type === "url" && (
        <img src="/wa-icon-url.png" width={14} height={14} alt="" style={{ filter: "var(--wa-btn-icon-filter)" }} />
      )}
      {button.type === "flow" && (
        <img src="/wa-icon-flow.png" width={14} height={14} alt="" style={{ filter: "var(--wa-btn-icon-filter)" }} />
      )}
      {label}
    </Button>
  );
}

const CarouselTemplate = React.forwardRef<HTMLDivElement, CarouselTemplateProps>(
  ({ className, body, cards, timestamp, ...props }, ref) => {
    return (
      <div ref={ref} className={cn("font-wa w-full", className)} {...props}>
        {/* Optional intro bubble */}
        {body && (
          <div className="mb-1 max-w-[280px] rounded-lg bg-wa-bubble-incoming px-[9px] py-[6px] shadow-sm">
            <p className="text-[14.2px] leading-[19px] text-wa-text-primary">{body}</p>
            {timestamp && (
              <div className="mt-1 flex justify-end">
                <span className="text-[11px] text-wa-bubble-meta">{timestamp}</span>
              </div>
            )}
          </div>
        )}

        {/* Cards row */}
        <ScrollArea.Root className="pb-1">
          <ScrollArea.Viewport className="flex gap-2" style={{ scrollSnapType: "x mandatory" }}>
          <ScrollArea.Content className="flex gap-2">
          {cards.map((card, i) => (
            <div
              key={i}
              className="w-[220px] shrink-0 overflow-hidden rounded-lg bg-wa-bubble-incoming shadow-sm"
              style={{ scrollSnapAlign: "start" }}
            >
              {/* Card image */}
              <div className="h-[130px] w-full bg-wa-gray-200">
                {card.imageUrl ? (
                  <img src={card.imageUrl} alt="" className="h-full w-full object-cover" />
                ) : (
                  <div className="flex h-full items-center justify-center">
                    <svg viewBox="0 0 24 24" width="36" height="36" className="text-wa-gray-400">
                      <path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z" fill="currentColor" />
                    </svg>
                  </div>
                )}
              </div>

              {/* Card body */}
              <div className="px-[9px] py-[6px]">
                <p className="text-[13px] leading-[18px] text-wa-text-primary">{card.body}</p>
              </div>

              {/* Card buttons */}
              {card.buttons && card.buttons.length > 0 && (
                <div className="border-t border-wa-border">
                  {card.buttons.map((btn, j) => (
                    <div key={j} className={cn(j > 0 && "border-t border-wa-border")}>
                      <CardButton button={btn} />
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
          </ScrollArea.Content>
          </ScrollArea.Viewport>
          <ScrollArea.Scrollbar orientation="horizontal" className="flex h-1.5 flex-col px-[3px] py-[3px]">
            <ScrollArea.Thumb className="flex-1 rounded-full bg-wa-gray-300" />
          </ScrollArea.Scrollbar>
        </ScrollArea.Root>
      </div>
    );
  }
);
CarouselTemplate.displayName = "CarouselTemplate";

export { CarouselTemplate };

"use client";

import * as React from "react";
import { Button } from "@base-ui/react/button";
import { cn } from "@/lib/utils";
import "@/components/ui/whatsapp/styles/whatsapp.css";

// ─── Types ────────────────────────────────────────────────────────────────────

type HeaderType = "text" | "image" | "video" | "document" | "location";

interface LocationHeader {
  name: string;
  address: string;
  imageUrl?: string;
}

interface TemplateHeader {
  type: HeaderType;
  text?: string;
  imageUrl?: string;
  videoUrl?: string;
  documentName?: string;
  location?: LocationHeader;
}

export type TemplateButton =
  // CTA — opens URL in browser
  | { type: "url";          label: string; url?: string }
  // CTA — initiates phone call
  | { type: "phone_number"; label: string; phone_number?: string }
  // User reply with pre-set text
  | { type: "quick_reply";  label: string }
  // Copies a coupon/promo code to clipboard
  | { type: "copy_code";    label?: string; code?: string }
  // Opens a WhatsApp Flow
  | { type: "flow";         label: string }
  // Opens a WhatsApp Catalog
  | { type: "catalog";      label?: string }
  // One-tap autofill OTP (authentication templates)
  | { type: "otp";          label?: string }
  // Calling permission request (custom display type)
  | { type: "call_permission"; bizName: string };

export interface TemplateBubbleProps
  extends React.HTMLAttributes<HTMLDivElement> {
  variant?: "incoming" | "outgoing";
  header?: TemplateHeader;
  body: string;
  footer?: string;
  buttons?: TemplateButton[];
  timestamp?: string;
}

// ─── Variable highlighting ─────────────────────────────────────────────────

function BodyText({ text }: { text: string }) {
  const parts = text.split(/(\{\{[^}]+\}\}|\{[^}]+\})/g);
  return (
    <>
      {parts.map((part, i) =>
        /^\{/.test(part) ? (
          <span key={i} className="text-wa-emerald-600">
            {part}
          </span>
        ) : (
          <React.Fragment key={i}>{part}</React.Fragment>
        )
      )}
    </>
  );
}

// ─── Header variants ──────────────────────────────────────────────────────────

function ImageHeader({ imageUrl }: { imageUrl?: string }) {
  return (
    <div className="h-[180px] w-full overflow-hidden rounded-t-lg" style={{ backgroundColor: "var(--wa-placeholder-bg)" }}>
      {imageUrl ? (
        <img src={imageUrl} alt="" className="h-full w-full object-cover" />
      ) : (
        <div className="flex h-full items-center justify-center">
          <img src="/wa-header-image.png" width={60} height={60} alt="" style={{ filter: "var(--wa-placeholder-icon)" }} />
        </div>
      )}
    </div>
  );
}

function VideoHeader({ videoUrl }: { videoUrl?: string }) {
  return (
    <div className="h-[180px] w-full overflow-hidden rounded-t-lg" style={{ backgroundColor: "var(--wa-placeholder-bg)" }}>
      {videoUrl ? (
        <video src={videoUrl} className="h-full w-full object-cover" />
      ) : (
        <div className="flex h-full items-center justify-center">
          <img src="/wa-header-video.png" width={60} height={60} alt="" />
        </div>
      )}
    </div>
  );
}

function DocumentHeader({ documentName }: { documentName?: string }) {
  return (
    <div className="flex h-[130px] w-full flex-col items-center justify-center gap-2 rounded-t-lg" style={{ backgroundColor: "var(--wa-placeholder-bg)" }}>
      <img src="/wa-header-document.png" width={52} height={52} alt="" style={{ filter: "var(--wa-placeholder-icon)" }} />
      {documentName && (
        <span className="text-[12px]" style={{ color: "var(--wa-icon-lighter)" }}>{documentName}</span>
      )}
    </div>
  );
}

function LocationHeader({ location }: { location?: LocationHeader }) {
  return (
    <div className="relative h-[160px] w-full overflow-hidden rounded-t-lg" style={{ backgroundColor: "var(--wa-placeholder-bg)" }}>
      {location?.imageUrl ? (
        <img src={location.imageUrl} alt="" className="h-full w-full object-cover" />
      ) : (
        <div className="flex h-full items-center justify-center">
          <img src="/wa-header-location.png" width={60} height={60} alt="" style={{ filter: "var(--wa-placeholder-icon)" }} />
        </div>
      )}
      {(location?.name || location?.address) && (
        <div className="absolute bottom-0 left-0 right-0 bg-black/30 px-3 py-2">
          {location.name && (
            <p className="text-[13px] font-medium text-white"><BodyText text={location.name} /></p>
          )}
          {location.address && (
            <p className="text-[12px] text-white/80"><BodyText text={location.address} /></p>
          )}
        </div>
      )}
    </div>
  );
}

// ─── Icons ────────────────────────────────────────────────────────────────────

const ICONS: Partial<Record<TemplateButton["type"], React.ReactNode>> = {
  url:          <img src="/wa-icon-url.png"   width={16} height={16} alt="" style={{ filter: "var(--wa-btn-icon-filter)" }} />,
  phone_number: <img src="/wa-icon-phone.png" width={16} height={16} alt="" style={{ filter: "var(--wa-btn-icon-filter)" }} />,
  quick_reply:  <img src="/wa-icon-phone.png" width={16} height={16} alt="" style={{ filter: "var(--wa-btn-icon-filter)" }} />,
  flow:         <img src="/wa-icon-flow.png"  width={16} height={16} alt="" style={{ filter: "var(--wa-btn-icon-filter)" }} />,
  catalog:      <img src="/wa-icon-url.png"   width={16} height={16} alt="" style={{ filter: "var(--wa-btn-icon-filter)" }} />,
  // copy_code / otp — inline SVG clipboard icon
  copy_code: (
    <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" style={{ filter: "var(--wa-btn-icon-filter)" }}>
      <path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/>
    </svg>
  ),
  otp: (
    <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" style={{ filter: "var(--wa-btn-icon-filter)" }}>
      <path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/>
    </svg>
  ),
};

// ─── Buttons ──────────────────────────────────────────────────────────────────

function TemplateButtonRow({ button }: { button: TemplateButton }) {
  const [copied, setCopied] = React.useState(false);
  const base = "flex w-full items-center justify-center gap-1.5 py-[10px] text-[14px] font-medium text-wa-emerald-500";

  const renderEl = (() => {
    if (button.type === "url" && button.url)
      return <a href={button.url} target="_blank" rel="noopener noreferrer" />;
    if (button.type === "phone_number" && button.phone_number)
      return <a href={`tel:${button.phone_number}`} />;
    return undefined;
  })();

  if (button.type === "call_permission") {
    return (
      <Button className={cn(base, "flex-col gap-0.5 py-3 text-wa-text-primary")}>
        <div className="flex items-center gap-2">
          <div className="flex h-9 w-9 items-center justify-center rounded-full bg-wa-emerald-500 text-white">
            <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
              <path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" />
            </svg>
          </div>
          <span className="text-[14px] font-medium">
            Can <span className="font-semibold">{button.bizName}</span> call you?
          </span>
        </div>
      </Button>
    );
  }

  const label =
    button.type === "copy_code" ? (button.label ?? "Copy offer code") :
    button.type === "otp"       ? (button.label ?? "Copy code") :
    button.type === "catalog"   ? (button.label ?? "View catalog") :
    "label" in button           ? button.label : "";

  const isCopyType = button.type === "copy_code" || button.type === "otp";
  const copyCode = isCopyType && "code" in button ? button.code : undefined;

  const handleClick = copyCode
    ? () => {
        navigator.clipboard.writeText(copyCode);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      }
    : undefined;

  return (
    <Button
      render={renderEl}
      nativeButton={renderEl == null}
      className={base}
      onClick={handleClick}
    >
      {copied ? (
        <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" style={{ filter: "var(--wa-btn-icon-filter)" }}>
          <path d="M9 16.2l-3.5-3.5-1.4 1.4L9 19 21 7l-1.4-1.4L9 16.2z"/>
        </svg>
      ) : (
        ICONS[button.type] ?? null
      )}
      {copied ? "Copied!" : label}
    </Button>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────

const TemplateBubble = React.forwardRef<HTMLDivElement, TemplateBubbleProps>(
  ({ className, variant = "incoming", header, body, footer, buttons = [], timestamp, ...props }, ref) => {
    const hasButtons = buttons.length > 0;
    const isOutgoing = variant === "outgoing";

    return (
      <div
        ref={ref}
        className={cn("font-wa w-full max-w-[320px]", className)}
        {...props}
      >
        {/* Bubble */}
        <div className={cn("overflow-hidden rounded-lg shadow-sm", isOutgoing ? "bg-wa-bubble-outgoing" : "bg-wa-bubble-incoming")}>
          {/* Header */}
          {header?.type === "image" && <ImageHeader imageUrl={header.imageUrl} />}
          {header?.type === "video" && <VideoHeader videoUrl={header.videoUrl} />}
          {header?.type === "document" && <DocumentHeader documentName={header.documentName} />}
          {header?.type === "location" && <LocationHeader location={header.location} />}

          {/* Body */}
          <div className="px-[9px] pb-2 pt-[6px]">
            {header?.type === "text" && header.text && (
              <p className="mb-1 text-[14.2px] font-bold leading-[19px] text-wa-text-primary">
                <BodyText text={header.text} />
              </p>
            )}
            <p className="text-[14.2px] leading-[19px] text-wa-text-primary">
              <BodyText text={body} />
            </p>
            {footer && (
              <p className="mt-1 text-[12px] leading-[16px] text-wa-text-secondary">
                {footer}
              </p>
            )}
            {timestamp && (
              <div className="mt-1 flex justify-end">
                <span className="text-[11px] text-wa-bubble-meta">{timestamp}</span>
              </div>
            )}
          </div>

          {/* Buttons */}
          {hasButtons && (
            <div className="border-t border-wa-border">
              {buttons.map((btn, i) => (
                <div key={i} className={cn(i > 0 && "border-t border-wa-border")}>
                  <TemplateButtonRow button={btn} />
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    );
  }
);
TemplateBubble.displayName = "TemplateBubble";

export { TemplateBubble };

/*
 * WhatsApp UI Design Tokens
 * Extracted from web.whatsapp.com WDS (WhatsApp Design System)
 */

@theme inline {
  /* === Primary Brand Colors === */
  --color-wa-green-50: var(--wa-green-50);
  --color-wa-green-75: var(--wa-green-75);
  --color-wa-green-100: var(--wa-green-100);
  --color-wa-green-200: var(--wa-green-200);
  --color-wa-green-300: var(--wa-green-300);
  --color-wa-green-400: var(--wa-green-400);
  --color-wa-green-450: var(--wa-green-450);
  --color-wa-green-500: var(--wa-green-500);
  --color-wa-green-600: var(--wa-green-600);
  --color-wa-green-700: var(--wa-green-700);
  --color-wa-green-750: var(--wa-green-750);
  --color-wa-green-800: var(--wa-green-800);

  /* === Emerald (Teal) === */
  --color-wa-emerald-400: var(--wa-emerald-400);
  --color-wa-emerald-500: var(--wa-emerald-500);
  --color-wa-emerald-600: var(--wa-emerald-600);

  /* === Neutral Gray === */
  --color-wa-gray-50: var(--wa-gray-50);
  --color-wa-gray-75: var(--wa-gray-75);
  --color-wa-gray-100: var(--wa-gray-100);
  --color-wa-gray-200: var(--wa-gray-200);
  --color-wa-gray-300: var(--wa-gray-300);
  --color-wa-gray-400: var(--wa-gray-400);
  --color-wa-gray-500: var(--wa-gray-500);
  --color-wa-gray-600: var(--wa-gray-600);
  --color-wa-gray-700: var(--wa-gray-700);
  --color-wa-gray-800: var(--wa-gray-800);
  --color-wa-gray-850: var(--wa-gray-850);
  --color-wa-gray-900: var(--wa-gray-900);
  --color-wa-gray-1000: var(--wa-gray-1000);

  /* === Sky Blue (Read Receipts) === */
  --color-wa-sky-blue-300: var(--wa-sky-blue-300);
  --color-wa-sky-blue-400: var(--wa-sky-blue-400);

  /* === Red (Destructive/Negative) === */
  --color-wa-red-300: var(--wa-red-300);
  --color-wa-red-400: var(--wa-red-400);

  /* === Cobalt === */
  --color-wa-cobalt-300: var(--wa-cobalt-300);
  --color-wa-cobalt-400: var(--wa-cobalt-400);

  /* === Persistent/Brand === */
  --color-wa-verified: var(--wa-verified);
  --color-wa-always-white: var(--wa-always-white);
  --color-wa-always-black: var(--wa-always-black);

  /* === Profile Photo Avatars === */
  --color-wa-avatar-brown: var(--wa-avatar-brown);
  --color-wa-avatar-cobalt: var(--wa-avatar-cobalt);
  --color-wa-avatar-green: var(--wa-avatar-green);
  --color-wa-avatar-orange: var(--wa-avatar-orange);
  --color-wa-avatar-pink: var(--wa-avatar-pink);
  --color-wa-avatar-purple: var(--wa-avatar-purple);
  --color-wa-avatar-red: var(--wa-avatar-red);
  --color-wa-avatar-sky-blue: var(--wa-avatar-sky-blue);
  --color-wa-avatar-teal: var(--wa-avatar-teal);
  --color-wa-avatar-yellow: var(--wa-avatar-yellow);

  /* === Semantic Colors (theme-aware) === */
  --color-wa-bg: var(--wa-bg);
  --color-wa-bg-deeper: var(--wa-bg-deeper);
  --color-wa-bg-wash: var(--wa-bg-wash);
  --color-wa-panel-bg: var(--wa-panel-bg);
  --color-wa-panel-header-bg: var(--wa-panel-header-bg);
  --color-wa-conversation-bg: var(--wa-conversation-bg);
  --color-wa-compose-bg: var(--wa-compose-bg);

  --color-wa-text-primary: var(--wa-text-primary);
  --color-wa-text-secondary: var(--wa-text-secondary);
  --color-wa-text-deemphasized: var(--wa-text-deemphasized);

  --color-wa-bubble-outgoing: var(--wa-bubble-outgoing);
  --color-wa-bubble-incoming: var(--wa-bubble-incoming);
  --color-wa-bubble-system: var(--wa-bubble-system);
  --color-wa-bubble-meta: var(--wa-bubble-meta);

  --color-wa-border: var(--wa-border);
  --color-wa-divider: var(--wa-divider);

  --color-wa-primary: var(--wa-primary);
  --color-wa-primary-hover: var(--wa-primary-hover);
  --color-wa-icon-default: var(--wa-icon-default);
  --color-wa-icon-lighter: var(--wa-icon-lighter);
  --color-wa-hover: var(--wa-hover);
  --color-wa-active: var(--wa-active);

  --color-wa-read: var(--wa-read);
  --color-wa-delivered: var(--wa-delivered);

  --color-wa-unread-marker: var(--wa-unread-marker);
  --color-wa-typing-dot: var(--wa-typing-dot);
  --color-wa-input-bg: var(--wa-input-bg);
  --color-wa-input-border: var(--wa-input-border);

  --color-wa-wallpaper-bg: var(--wa-wallpaper-bg);
  --color-wa-wallpaper-fg: var(--wa-wallpaper-fg);

  /* === Additional Color Scales === */
  --color-wa-teal-300: var(--wa-teal-300);
  --color-wa-teal-400: var(--wa-teal-400);
  --color-wa-teal-500: var(--wa-teal-500);

  --color-wa-purple-300: var(--wa-purple-300);
  --color-wa-purple-400: var(--wa-purple-400);

  --color-wa-orange-300: var(--wa-orange-300);
  --color-wa-orange-400: var(--wa-orange-400);

  --color-wa-yellow-300: var(--wa-yellow-300);
  --color-wa-yellow-400: var(--wa-yellow-400);

  --color-wa-pink-300: var(--wa-pink-300);
  --color-wa-pink-400: var(--wa-pink-400);

  /* === Attachment Type Colors === */
  --color-wa-attachment-document: var(--wa-attachment-document);
  --color-wa-attachment-audio: var(--wa-attachment-audio);
  --color-wa-attachment-photo: var(--wa-attachment-photo);
  --color-wa-attachment-contact: var(--wa-attachment-contact);
  --color-wa-attachment-camera: var(--wa-attachment-camera);
  --color-wa-attachment-sticker: var(--wa-attachment-sticker);
  --color-wa-attachment-poll: var(--wa-attachment-poll);
  --color-wa-attachment-catalog: var(--wa-attachment-catalog);

  /* === Semantic Text === */
  --color-wa-text-disabled: var(--wa-text-disabled);
  --color-wa-text-critical: var(--wa-text-critical);
  --color-wa-text-success: var(--wa-text-success);
  --color-wa-text-action: var(--wa-text-action);
  --color-wa-system-msg: var(--wa-system-msg);
  --color-wa-primary-title: var(--wa-primary-title);

  /* === Typography === */
  --font-wa: "Segoe UI", "Helvetica Neue", Helvetica, "Lucida Grande", Arial,
    Ubuntu, Cantarell, "Fira Sans", sans-serif;

  /* === Layout Constants === */
  --spacing-wa-sidebar-width: var(--wa-sidebar-width);
  --spacing-wa-sidebar-min-width: var(--wa-sidebar-min-width);
  --spacing-wa-header-height: var(--wa-header-height);
  --spacing-wa-compose-height: var(--wa-compose-height);
  --spacing-wa-chat-spacing: var(--wa-chat-spacing);
  --spacing-wa-avatar-sm: var(--wa-avatar-size-sm);
  --spacing-wa-avatar-md: var(--wa-avatar-size-md);
  --spacing-wa-avatar-lg: var(--wa-avatar-size-lg);

  /* === Border Radius === */
  --radius-wa-bubble: var(--wa-bubble-radius);

  /* === Animation === */
  --animate-wa-typing-bounce: wa-typing-bounce 1.2s ease-in-out infinite;
}

@keyframes wa-typing-bounce {
  0%,
  60%,
  100% {
    transform: translateY(0);
  }
  30% {
    transform: translateY(-4px);
  }
}

